     1→import type Player from '../objects/Player';
     2→
     3→/** GameScene이 CharacterAbility에 노출하는 API */
     4→export interface GameSceneAPI {
     5→  readonly score: number;
     6→  readonly player: Player;
     7→  readonly difficultyLevel: number;
     8→  readonly baseSpeed: number;
     9→  readonly isClassicMode: boolean;
    10→
    11→  readonly poops: Phaser.Physics.Arcade.Group;
    12→  readonly goldPoops: Phaser.Physics.Arcade.Group;
    13→  readonly diamondPoops: Phaser.Physics.Arcade.Group;
    14→  readonly topazPoops: Phaser.Physics.Arcade.Group;
    15→  readonly rainbowPoops: Phaser.Physics.Arcade.Group;
    16→
    17→  /** Phaser.Scene — time / tweens / add / cameras / physics 접근용 */
    18→  readonly scene: Phaser.Scene;
    19→
    20→  updateScore(amount: number): void;
    21→  spawnGoldPoop(): void;
    22→  spawnDiamondPoop(): void;
    23→  spawnTopazPoop(): void;
    24→  spawnRainbowPoop(): void;
    25→  /** 특수 똥 수집 전체 처리 (카운트++, 점수, 획득 텍스트) */
    26→  collectGoldPoop(poop: Phaser.Physics.Arcade.Sprite): void;
    27→  collectDiamondPoop(poop: Phaser.Physics.Arcade.Sprite): void;
    28→  collectTopazPoop(poop: Phaser.Physics.Arcade.Sprite): void;
    29→  collectRainbowPoop(poop: Phaser.Physics.Arcade.Sprite): void;
    30→}
    31→
    32→/** 특수 똥 타입 */
    33→export type SpecialPoopType = 'gold' | 'diamond' | 'topaz' | 'rainbow';
    34→
    35→/** 캐릭터 능력 인터페이스 */
    36→export interface CharacterAbility {
    37→  /** create() 완료 후 호출 — 스프라이트·UI 초기화 */
    38→  onCreate(api: GameSceneAPI): void;
    39→
    40→  /** 플레이어 속도 보너스 (Player 생성 전 GameScene에서 읽음) */
