content.content:
     1→import Phaser from 'phaser';
     2→import {
     3→  CHARACTERS,
     4→  getOwnedCharacters,
     5→  getSelectedCharacter,
     6→  setSelectedCharacter,
     7→  getDuplicateCount,
     8→  getAwakeningLevel,
     9→  type CharacterDef,
    10→} from '../utils/character';
    11→import { syncOwnedCharacters } from '../utils/gacha';
    12→
    13→// 그리드 설정
    14→const COLS = 3;
    15→const CARD_W = 100;
    16→const CARD_H = 120;
    17→const GAP_X = 15;
    18→const GAP_Y = 10;
    19→const GRID_LEFT = (400 - (COLS * CARD_W + (COLS - 1) * GAP_X)) / 2; // 35px
    20→const GRID_TOP = 145;
    21→
    22→// 스크롤 영역 (헤더 아래 ~ 하단 버튼 위)
    23→const SCROLL_TOP = 128;
    24→const SCROLL_BOTTOM = 548;
    25→
    26→export default class CharacterSelectScene extends Phaser.Scene {
    27→  private selectedId: string = 'chibi';
    28→  private ownedIds: string[] = [];
    29→  private _preSyncDupCounts: Map<string, number> = new Map();
    30→  private cardHighlights: Map<string, Phaser.GameObjects.Rectangle> = new Map();
    31→
    32→  // 스크롤
    33→  private cardsContainer!: Phaser.GameObjects.Container;
    34→  private scrollOffset = 0;
    35→  private maxScrollOffset = 0;
    36→  private pointerDownY = 0;
    37→  private pointerDownScrollY = 0;
    38→  private hasDragged = false;
    39→  private hasPointerDownInScene = false; // 이 씬에서 pointerdown이 발생했는지 추적 (bleed-through 방지)
    40→
    41→  // 동적 갱신용 ref
    42→  private headerNameText!: Phaser.GameObjects.Text;
    43→  private bgImage!: Phaser.GameObjects.Image;
    44→
    45→  // 상세 정보 패널
    46→  private detailPanel: Phaser.GameObjects.Container | null = null;
    47→  private infoPanel: Phaser.GameObjects.Container | null = null;
    48→  private detailVideo: Phaser.GameObjects.Video | null = null;
    49→  private fitVideoTimers: Phaser.Time.TimerEvent[] = [];
    50→
    51→  constructor() {
    52→    super('CharacterSelectScene');
    53→  }
    54→
    55→  preload() {
    56→    for (const char of CHARACTERS) {
    57→      if (!this.textures.exists(char.imageKey)) {
    58→        this.load.image(char.imageKey, char.imagePath);
    59→      }
    60→      if (!this.textures.exists(char.illustKey)) {
    61→        this.load.image(char.illustKey, char.illustPath);
    62→      }
    63→      if (char.videoKey && char.videoPath && !this.cache.video.exists(char.videoKey)) {
    64→        this.load.video(char.videoKey, char.videoPath);
    65→      }
    66→    }
    67→  }
    68→
    69→  create() {
    70→    this.selectedId = getSelectedCharacter();
    71→    this.ownedIds = getOwnedCharacters();
    72→    this.scrollOffset = 0;
    73→    this.hasDragged = false;
    74→    this.hasPointerDownInScene = false;
    75→    this.cardHighlights.clear();
    76→
    77→    // 동기화 전 각성 수치 스냅샷 (동기화 후 변화 감지용)
    78→    this._preSyncDupCounts = new Map(
    79→      CHARACTERS
    80→        .filter(c => this.ownedIds.includes(c.id) && c.grade !== '등급외')
    81→        .map(c => [c.id, getDuplicateCount(c.id)])
    82→    );
    83→
    84→    // 서버 DB와 동기화 — 소유 목록 or 각성 수치가 바뀐 경우 씬 재시작해서 카드 갱신
    85→    syncOwnedCharacters().then(synced => {
    86→      if (!this.scene.isActive()) return;
    87→      const ownedChanged = synced.length !== this.ownedIds.length ||
    88→        synced.some(id => !this.ownedIds.includes(id));
    89→      // 각성 수치 변화 여부: 동기화 후 localStorage의 duplicate_count가 달라졌으면 재시작
    90→      const awakeChanged = CHARACTERS.some(c =>
    91→        synced.includes(c.id) && c.grade !== '등급외' &&
    92→        getDuplicateCount(c.id) !== this._preSyncDupCounts.get(c.id)
    93→      );
    94→      if (ownedChanged || awakeChanged) this.scene.restart();
    95→    }).catch(() => { /* 네트워크 오류 시 로컬 상태 유지 */ });
    96→
    97→    const selectedDef = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
    98→
    99→    // ── 배경: 선택된 캐릭터 일러스트 ───────────────────────────────────
   100→    this.bgImage = this.add.image(200, 300, selectedDef.illustKey);
   101→    this.bgImage.setDisplaySize(400, 600);
   102→
   103→    // ── 헤더 (고정) ─────────────────────────────────────────────────────
   104→    this.add.text(200, 40, '캐릭터 선택', {
   105→      fontSize: '26px',
   106→      color: '#ffffff',
   107→      fontStyle: 'bold',
   108→      stroke: '#000',
   109→      strokeThickness: 4,
   110→    }).setOrigin(0.5);
   111→
   112→    this.headerNameText = this.add.text(200, 80, `현재: ${selectedDef.name}`, {
   113→      fontSize: '16px',
   114→      color: selectedDef.gradeColor,
   115→      stroke: '#000',
   116→      strokeThickness: 3,
   117→    }).setOrigin(0.5);
   118→
   119→    this.add.text(200, 108, '수집한 캐릭터를 선택하세요', {
   120→      fontSize: '13px',
   121→      color: '#888888',
   122→    }).setOrigin(0.5);
   123→
   124→    // ── 스크롤 가능한 카드 컨테이너 ─────────────────────────────────────
   125→    this.cardsContainer = this.add.container(0, 0);
   126→
   127→    CHARACTERS.forEach((char, index) => {
   128→      const col = index % COLS;
   129→      const row = Math.floor(index / COLS);
   130→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
   131→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
   132→      this.createCharacterCard(char, x, y);
   133→    });
   134→
   135→    // 스크롤 최대 범위 계산
   136→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   137→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   138→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   139→
   140→    // 카드 영역 마스크 (스크롤 영역 밖 숨김)
   141→    const maskGfx = this.make.graphics({ x: 0, y: 0 });
   142→    maskGfx.fillStyle(0xffffff);
   143→    maskGfx.fillRect(0, SCROLL_TOP, 400, SCROLL_BOTTOM - SCROLL_TOP);
   144→    this.cardsContainer.setMask(maskGfx.createGeometryMask());
   145→
   146→    // ── 드래그 스크롤 입력 ───────────────────────────────────────────────
   147→    this.input.on('pointerdown', (p: Phaser.Input.Pointer) => {
   148→      this.hasPointerDownInScene = true;
   149→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   150→      if (p.y < SCROLL_TOP || p.y > SCROLL_BOTTOM) return;
   151→      this.pointerDownY = p.y;
   152→      this.pointerDownScrollY = this.scrollOffset;
   153→      this.hasDragged = false;
   154→    });
   155→
   156→    this.input.on('pointermove', (p: Phaser.Input.Pointer) => {
   157→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   158→      if (!p.isDown) return;
   159→      const dy = this.pointerDownY - p.y;
   160→      if (Math.abs(dy) > 5) {
   161→        this.hasDragged = true;
   162→        this.scrollOffset = Phaser.Math.Clamp(
   163→          this.pointerDownScrollY + dy,
   164→          0,
   165→          this.maxScrollOffset,
   166→        );
   167→        this.cardsContainer.setY(-this.scrollOffset);
   168→      }
   169→    });
   170→
   171→    this.input.on('pointerup', () => {
   172→      if (this.detailPanel) return; // 상세 패널 열려있으면 hasDragged 초기화 무시
   173→      // card pointerup 이벤트가 먼저 발생하므로 다음 프레임에 초기화
   174→      this.time.delayedCall(0, () => {
   175→        this.hasDragged = false;
   176→        this.hasPointerDownInScene = false;
   177→      });
   178→    });
   179→
   180→    // 마우스 휠
   181→    this.input.on(
   182→      'wheel',
   183→      (_p: Phaser.Input.Pointer, _go: unknown[], _dx: number, deltaY: number) => {
   184→        if (this.detailPanel) return; // 상세 패널 열려있으면 휠 스크롤 무시
   185→        this.scrollOffset = Phaser.Math.Clamp(
   186→          this.scrollOffset + deltaY * 0.5,
   187→          0,
   188→          this.maxScrollOffset,
   189→        );
   190→        this.cardsContainer.setY(-this.scrollOffset);
   191→      },
   192→    );
   193→
   194→    // ── 고정 UI ─────────────────────────────────────────────────────────
   195→    this.createBackButton();
   196→  }
   197→
   198→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
   199→    const isOwned = this.ownedIds.includes(char.id);
   200→    const isSelected = this.selectedId === char.id;
   201→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
   202→
   203→    // 카드 배경
   204→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
   205→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
   206→    this.cardsContainer.add(cardBg);
   207→
   208→    // 선택 하이라이트
   209→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
   210→    highlight.setStrokeStyle(3, 0xffffff);
   211→    highlight.setVisible(isSelected);
   212→    this.cardHighlights.set(char.id, highlight);
   213→    this.cardsContainer.add(highlight);
   214→
   215→    // 캐릭터 이미지
   216→    const img = this.add.image(x, y - 12, char.imageKey);
   217→    img.setDisplaySize(58, 85);
   218→    this.cardsContainer.add(img);
   219→
   220→    if (!isOwned) {
   221→      img.setTint(0x000000);
   222→      img.setAlpha(0.6);
   223→      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
   224→      this.cardsContainer.add(lock);
   225→    }
   226→
   227→    // 등급 배지
   228→    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
   229→      fontSize: '9px',
   230→      color: char.gradeColor,
   231→      fontStyle: 'bold',
   232→      backgroundColor: '#000000cc',
   233→      padding: { x: 3, y: 1 },
   234→    }).setOrigin(1, 0);
   235→    this.cardsContainer.add(badge);
   236→
   237→    // 각성 코어 (등급외 제외, 보유 캐릭터만)
   238→    if (isOwned && char.grade !== '등급외') {
   239→      const dupCount     = getDuplicateCount(char.id);
   240→      const awakeLevel   = getAwakeningLevel(char.grade, dupCount);
   241→      const gradeColor   = parseInt(char.gradeColor.replace('#', ''), 16);
   242→      const coreY        = y + CARD_H / 2 - 28;
   243→      const coreGap      = 10;
   244→      const gfx          = this.add.graphics();
   245→
   246→      for (let i = 0; i < 5; i++) {
   247→        const cx = x + (i - 2) * coreGap;
   248→        if (i < awakeLevel) {
   249→          // 충전된 코어: 외곽 글로우 + 내부 밝은 원
   250→          gfx.fillStyle(gradeColor, 0.25);
   251→          gfx.fillCircle(cx, coreY, 5.5);
   252→          gfx.fillStyle(gradeColor, 1);
   253→          gfx.fillCircle(cx, coreY, 3.5);
   254→          gfx.fillStyle(0xffffff, 0.55);
   255→          gfx.fillCircle(cx - 1, coreY - 1, 1.2);
   256→        } else {
   257→          // 빈 코어: 어두운 원 + 얇은 테두리
   258→          gfx.fillStyle(0x111111, 1);
   259→          gfx.fillCircle(cx, coreY, 3.5);
   260→          gfx.lineStyle(1, gradeColor, 0.35);
   261→          gfx.strokeCircle(cx, coreY, 3.5);
   262→        }
   263→      }
   264→      this.cardsContainer.add(gfx);
   265→    }
   266→
   267→    // 캐릭터 이름
   268→    const nameText = this.add.text(x, y + CARD_H / 2 - 16, char.name, {
   269→      fontSize: '12px',
   270→      color: isOwned ? '#ffffff' : '#555555',
   271→      fontStyle: 'bold',
   272→    }).setOrigin(0.5);
   273→    this.cardsContainer.add(nameText);
   274→
   275→    // 모든 카드 클릭 가능 (탭 → 상세 패널 열기)
   276→    cardBg.setInteractive({ useHandCursor: isOwned });
   277→
   278→    if (isOwned) {
   279→      cardBg.on('pointerover', () => {
   280→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x333333);
   281→      });
   282→      cardBg.on('pointerout', () => {
   283→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x222222);
   284→      });
   285→    }
   286→    // pointerup으로 상세 패널 열기 (드래그 스크롤과 구분, 이전 씬 bleed-through 방지)
   287→    cardBg.on('pointerup', () => {
   288→      if (!this.hasDragged && this.hasPointerDownInScene) this.showCharacterDetail(char.id);
   289→    });
   290→  }
   291→
   292→  private selectCharacter(id: string) {
   293→    // 이전 선택 하이라이트 제거
   294→    const prev = this.cardHighlights.get(this.selectedId);
   295→    if (prev) prev.setVisible(false);
   296→
   297→    this.selectedId = id;
   298→    setSelectedCharacter(id);
   299→
   300→    const next = this.cardHighlights.get(id);
   301→    if (next) next.setVisible(true);
   302→
   303→    // 헤더 직접 갱신 (씬 재시작 없이)
   304→    const def = CHARACTERS.find(c => c.id === id) ?? CHARACTERS[0];
   305→    this.headerNameText.setText(`현재: ${def.name}`);
   306→    this.headerNameText.setColor(def.gradeColor);
   307→    this.bgImage.setTexture(def.illustKey);
   308→  }
   309→
   310→  private showCharacterDetail(id: string): void {
   311→    this.hideCharacterDetail();
   312→
   313→    const def = CHARACTERS.find(c => c.id === id) ?? CHARACTERS[0];
   314→    const isOwned = this.ownedIds.includes(id);
   315→    const gradeColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
   316→
   317→    const panel = this.add.container(0, 0).setDepth(300);
   318→    this.detailPanel = panel;
   319→
   320→    // ── 클릭 투과 차단 레이어 (카드 목록으로 이벤트 전달 방지)
   321→    const blocker = this.add.rectangle(200, 300, 400, 600, 0x000000, 0).setInteractive();
   322→    panel.add(blocker);
   323→
   324→    // ── 일러스트 전체 화면 ───────────────────────────────────────────
   325→    const illust = this.add.image(200, 300, def.illustKey).setDisplaySize(400, 600);
   326→    panel.add(illust);
   327→
   328→    // ── 비디오 (일러스트와 같은 위치, 처음엔 숨김) ─────────────────
   329→    const hasVideo = !!(def.videoKey && this.cache.video.exists(def.videoKey));
   330→    const videoObj = hasVideo
   331→      ? this.add.video(200, 300, def.videoKey!).setDisplaySize(400, 600).setVisible(false)
   332→      : null;
   333→    if (videoObj) {
   334→      panel.add(videoObj);
   335→      this.detailVideo = videoObj;
   336→    }
   337→
   338→    // ── 하단 그라디언트 (위 투명 → 아래 짙은 어둠) ─────────────────
   339→    // 비디오/일러스트 위, 버튼 아래에 위치하도록 여기서 추가
   340→    const grad = this.add.graphics();
   341→    grad.fillGradientStyle(0x000000, 0x000000, 0x000000, 0x000000, 0, 0, 0.78, 0.78);
   342→    grad.fillRect(0, 380, 400, 220);
   343→    panel.add(grad);
   344→
   345→    // ── ✕ 닫기 버튼 (우상단 플로팅) ────────────────────────────────
   346→    const closeBg = this.add.circle(372, 38, 22, 0x000000, 0.55)
   347→      .setInteractive({ useHandCursor: true });
   348→    const closeBtn = this.add.text(372, 38, '✕', {
   349→      fontSize: '18px', color: '#cccccc',
   350→    }).setOrigin(0.5);
   351→    closeBg.on('pointerover', () => { closeBg.setFillStyle(0x333333, 0.8); closeBtn.setColor('#ffffff'); });
   352→    closeBg.on('pointerout',  () => { closeBg.setFillStyle(0x000000, 0.55); closeBtn.setColor('#cccccc'); });
