    77→    // 동기화 전 각성 수치 스냅샷 (동기화 후 변화 감지용)
    78→    this._preSyncDupCounts = new Map(
    79→      CHARACTERS
    80→        .filter(c => this.ownedIds.includes(c.id) && c.grade !== '등급외')
    81→        .map(c => [c.id, getDuplicateCount(c.id)])
    82→    );
