    90→      const awakeChanged = CHARACTERS.some(c =>
    91→        synced.includes(c.id) && c.grade !== '등급외' &&
    92→        getDuplicateCount(c.id) !== this._preSyncDupCounts.get(c.id)
    93→      );
    94→      if (ownedChanged || awakeChanged) this.scene.restart();
    95→    }).catch(() => { /* 네트워크 오류 시 로컬 상태 유지 */ });
    96→
    97→    const selectedDef = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
    98→
    99→    // ── 배경: 선택된 캐릭터 일러스트 ───────────────────────────────────
   100→    this.bgImage = this.add.image(200, 300, selectedDef.illustKey);
   101→    this.bgImage.setDisplaySize(400, 600);
   102→
   103→    // ── 헤더 (고정) ─────────────────────────────────────────────────────
