   105→      fontSize: '26px',
   106→      color: '#ffffff',
   107→      fontStyle: 'bold',
   108→      stroke: '#000',
   109→      strokeThickness: 4,
   110→    }).setOrigin(0.5);
   111→
   112→    this.headerNameText = this.add.text(200, 80, `현재: ${selectedDef.name}`, {
   113→      fontSize: '16px',
