   118→
   119→    this.add.text(200, 108, '수집한 캐릭터를 선택하세요', {
   120→      fontSize: '13px',
   121→      color: '#888888',
   122→    }).setOrigin(0.5);
   123→
   124→    // ── 스크롤 가능한 카드 컨테이너 ─────────────────────────────────────
   125→    this.cardsContainer = this.add.container(0, 0);
   126→
   127→    CHARACTERS.forEach((char, index) => {
   128→      const col = index % COLS;
   129→      const row = Math.floor(index / COLS);
   130→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
   131→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
   132→      this.createCharacterCard(char, x, y);
   133→    });
