   198→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
   199→    const isOwned = this.ownedIds.includes(char.id);
   200→    const isSelected = this.selectedId === char.id;
   201→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
   202→
   203→    // 카드 배경
   204→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
