   328→    // ── 비디오 (일러스트와 같은 위치, 처음엔 숨김) ─────────────────
   329→    const hasVideo = !!(def.videoKey && this.cache.video.exists(def.videoKey));
   330→    const videoObj = hasVideo
   331→      ? this.add.video(200, 300, def.videoKey!).setDisplaySize(400, 600).setVisible(false)
   332→      : null;
