   449→  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 400×600 캔버스에 cover */
   450→  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
   451→    const W = 400, H = 600;
   452→    vid.setDisplaySize(W, H);
   453→
   454→    const applyContain = () => {
   455→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   456→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   457→      const nw = el?.videoWidth  || 0;
   458→      const nh = el?.videoHeight || 0;
   459→      if (nw > 0 && nh > 0) {
   460→        const scale = Math.max(W / nw, H / nh);
   461→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   462→      }
   463→    };
   464→
   465→    vid.once('play', applyContain);
   466→    this.fitVideoTimers.push(this.time.delayedCall(100, applyContain));
   467→    this.fitVideoTimers.push(this.time.delayedCall(500, applyContain));
   468→  }
