   118→
   119→    this.add.text(200, 108, '수집한 캐릭터를 선택하세요', {
   120→      fontSize: '13px',
   121→      color: '#888888',
   122→    }).setOrigin(0.5);
   123→
   124→    // ── 스크롤 가능한 카드 컨테이너 ─────────────────────────────────────
   125→    this.cardsContainer = this.add.container(0, 0);
   126→
   127→    CHARACTERS.forEach((char, index) => {
   128→      const col = index % COLS;
   129→      const row = Math.floor(index / COLS);
   130→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
   131→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
   132→      this.createCharacterCard(char, x, y);
   133→    });
   134→
   135→    // 스크롤 최대 범위 계산
   136→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   137→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   138→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   139→
   140→    // 카드 영역 마스크 (스크롤 영역 밖 숨김)
   141→    const maskGfx = this.make.graphics({ x: 0, y: 0 });
   142→    maskGfx.fillStyle(0xffffff);
   143→    maskGfx.fillRect(0, SCROLL_TOP, 400, SCROLL_BOTTOM - SCROLL_TOP);
   144→    this.cardsContainer.setMask(maskGfx.createGeometryMask());
   145→
   146→    // ── 드래그 스크롤 입력 ───────────────────────────────────────────────
   147→    this.input.on('pointerdown', (p: Phaser.Input.Pointer) => {
   148→      this.hasPointerDownInScene = true;
   149→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   150→      if (p.y < SCROLL_TOP || p.y > SCROLL_BOTTOM) return;
   151→      this.pointerDownY = p.y;
   152→      this.pointerDownScrollY = this.scrollOffset;
   153→      this.hasDragged = false;
   154→    });
   155→
   156→    this.input.on('pointermove', (p: Phaser.Input.Pointer) => {
   157→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   158→      if (!p.isDown) return;
   159→      const dy = this.pointerDownY - p.y;
   160→      if (Math.abs(dy) > 5) {
   161→        this.hasDragged = true;
   162→        this.scrollOffset = Phaser.Math.Clamp(
   163→          this.pointerDownScrollY + dy,
   164→          0,
   165→          this.maxScrollOffset,
   166→        );
   167→        this.cardsContainer.setY(-this.scrollOffset);
   168→      }
   169→    });
   170→
   171→    this.input.on('pointerup', () => {
   172→      if (this.detailPanel) return; // 상세 패널 열려있으면 hasDragged 초기화 무시
   173→      // card pointerup 이벤트가 먼저 발생하므로 다음 프레임에 초기화
   174→      this.time.delayedCall(0, () => {
   175→        this.hasDragged = false;
   176→        this.hasPointerDownInScene = false;
   177→      });
   178→    });
   179→
   180→    // 마우스 휠
   181→    this.input.on(
   182→      'wheel',
   183→      (_p: Phaser.Input.Pointer, _go: unknown[], _dx: number, deltaY: number) => {
   184→        if (this.detailPanel) return; // 상세 패널 열려있으면 휠 스크롤 무시
   185→        this.scrollOffset = Phaser.Math.Clamp(
   186→          this.scrollOffset + deltaY * 0.5,
   187→          0,
   188→          this.maxScrollOffset,
   189→        );
   190→        this.cardsContainer.setY(-this.scrollOffset);
   191→      },
   192→    );
   193→
   194→    // ── 고정 UI ─────────────────────────────────────────────────────────
   195→    this.createBackButton();
   196→  }
