   198→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
   199→    const isOwned = this.ownedIds.includes(char.id);
   200→    const isSelected = this.selectedId === char.id;
   201→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
   202→
   203→    // 카드 배경
   204→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
   205→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
   206→    this.cardsContainer.add(cardBg);
   207→
   208→    // 선택 하이라이트
   209→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
   210→    highlight.setStrokeStyle(3, 0xffffff);
   211→    highlight.setVisible(isSelected);
   212→    this.cardHighlights.set(char.id, highlight);
   213→    this.cardsContainer.add(highlight);
   214→
   215→    // 캐릭터 이미지
   216→    const img = this.add.image(x, y - 12, char.imageKey);
   217→    img.setDisplaySize(58, 85);
   218→    this.cardsContainer.add(img);
   219→
   220→    if (!isOwned) {
   221→      img.setTint(0x000000);
   222→      img.setAlpha(0.6);
   223→      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
   224→      this.cardsContainer.add(lock);
   225→    }
   226→
   227→    // 등급 배지
   228→    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
   229→      fontSize: '9px',
   230→      color: char.gradeColor,
   231→      fontStyle: 'bold',
   232→      backgroundColor: '#000000cc',
   233→      padding: { x: 3, y: 1 },
   234→    }).setOrigin(1, 0);
   235→    this.cardsContainer.add(badge);
   236→
   237→    // 각성 코어 (등급외 제외, 보유 캐릭터만)
   238→    if (isOwned && char.grade !== '등급외') {
   239→      const dupCount     = getDuplicateCount(char.id);
   240→      const awakeLevel   = getAwakeningLevel(char.grade, dupCount);
   241→      const gradeColor   = parseInt(char.gradeColor.replace('#', ''), 16);
   242→      const coreY        = y + CARD_H / 2 - 28;
   243→      const coreGap      = 10;
   244→      const gfx          = this.add.graphics();
   245→
   246→      for (let i = 0; i < 5; i++) {
   247→        const cx = x + (i - 2) * coreGap;
   248→        if (i < awakeLevel) {
   249→          // 충전된 코어: 외곽 글로우 + 내부 밝은 원
   250→          gfx.fillStyle(gradeColor, 0.25);
   251→          gfx.fillCircle(cx, coreY, 5.5);
   252→          gfx.fillStyle(gradeColor, 1);
   253→          gfx.fillCircle(cx, coreY, 3.5);
   254→          gfx.fillStyle(0xffffff, 0.55);
   255→          gfx.fillCircle(cx - 1, coreY - 1, 1.2);
   256→        } else {
   257→          // 빈 코어: 어두운 원 + 얇은 테두리
   258→          gfx.fillStyle(0x111111, 1);
   259→          gfx.fillCircle(cx, coreY, 3.5);
   260→          gfx.lineStyle(1, gradeColor, 0.35);
   261→          gfx.strokeCircle(cx, coreY, 3.5);
   262→        }
   263→      }
   264→      this.cardsContainer.add(gfx);
   265→    }
   266→
   267→    // 캐릭터 이름
   268→    const nameText = this.add.text(x, y + CARD_H / 2 - 16, char.name, {
   269→      fontSize: '12px',
   270→      color: isOwned ? '#ffffff' : '#555555',
   271→      fontStyle: 'bold',
   272→    }).setOrigin(0.5);
   273→    this.cardsContainer.add(nameText);
   274→
   275→    // 모든 카드 클릭 가능 (탭 → 상세 패널 열기)
   276→    cardBg.setInteractive({ useHandCursor: isOwned });
   277→
   278→    if (isOwned) {
   279→      cardBg.on('pointerover', () => {
   280→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x333333);
   281→      });
   282→      cardBg.on('pointerout', () => {
   283→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x222222);
   284→      });
   285→    }
   286→    // pointerup으로 상세 패널 열기 (드래그 스크롤과 구분, 이전 씬 bleed-through 방지)
   287→    cardBg.on('pointerup', () => {
   288→      if (!this.hasDragged && this.hasPointerDownInScene) this.showCharacterDetail(char.id);
   289→    });
   290→  }
