   410→      const lockBg = this.add.rectangle(292, BTN_Y, BTN_W, BTN_H, 0x1a1a1a)
   411→        .setStrokeStyle(1.5, 0x444444);
   412→      const lockLabel = this.add.text(292, BTN_Y, '🔒  미보유', {
