   434→      illust.setInteractive({ useHandCursor: true });
   435→      illust.on('pointerup', startVideo);
   436→
   437→      // 비디오 탭 또는 재생 완료 → 일러스트로 복귀
   438→      const stopVideo = () => {
   439→        videoObj!.stop();
   440→        videoObj!.setVisible(false);
   441→        illust.setVisible(true);
   442→      };
   443→      videoObj.setInteractive({ useHandCursor: true });
   444→      videoObj.on('pointerup', stopVideo);
   445→      videoObj.on('complete', stopVideo);
   446→    }
   447→  }
