   494→  private showInfoPanel(def: CharacterDef): void {
   495→    this.hideInfoPanel();
   496→
   497→    const gradeColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
   498→    const panel = this.add.container(0, 0).setDepth(400);
   499→    this.infoPanel = panel;
   500→
   501→    // ── 각성 보너스 계산 ──────────────────────────────────────────────
   502→    const dupCount   = getDuplicateCount(def.id);
   503→    const awakeLevel = getAwakeningLevel(def.grade, dupCount);
   504→    const awakeBonusLines: string[] = [];
   505→    if (def.grade !== '등급외') {
   506→      if (awakeLevel >= 1) {
   507→        const spd = def.id === 'maehwa' ? 5 : def.grade === 'UR' ? 15 : def.grade === 'SR' ? 10 : 5;
   508→        awakeBonusLines.push(`★1 각성: 이동속도 +${spd} px/s`);
   509→      }
   510→      if (awakeLevel >= 2) {
   511→        if (def.id === 'maehwa') {
   512→          awakeBonusLines.push('★2 각성: 특수 똥 수집 시 +5점');
   513→        } else {
   514→          const spd = def.grade === 'UR' ? 20 : def.grade === 'SR' ? 15 : 10;
   515→          awakeBonusLines.push(`★2 각성: 이동속도 +${spd} px/s (누적)`);
   516→        }
   517→      }
   518→    }
   519→    const awakeBonusText = awakeBonusLines.join('\n');
   520→
   521→    // 반투명 배경 (클릭 시 닫기)
   522→    const overlay = this.add.rectangle(200, 300, 400, 600, 0x000000, 0.80)
   523→      .setInteractive();
   524→    overlay.on('pointerup', () => this.hideInfoPanel());
   525→    panel.add(overlay);
   526→
   527→    // ── 카드 크기 계산 (텍스트 높이 선측정) ─────────────────────────
   528→    const B_LEFT = 30;
   529→    const CARD_W = 370;
   530→    const WRAP_W = CARD_W - 40; // 좌(15px)·우(25px) 여백 제외한 실제 텍스트 폭
   531→    const HEADER_H = 60;  // 스프라이트+이름+구분선 영역
