    42→  private headerNameText!: Phaser.GameObjects.Text;
    43→  private bgImage!: Phaser.GameObjects.Image;
    44→
    45→  // 상세 정보 패널
    46→  private detailPanel: Phaser.GameObjects.Container | null = null;
    47→  private infoPanel: Phaser.GameObjects.Container | null = null;
