    59→      }
    60→      if (!this.textures.exists(char.illustKey)) {
    61→        this.load.image(char.illustKey, char.illustPath);
    62→      }
    63→      if (char.videoKey && char.videoPath && !this.cache.video.exists(char.videoKey)) {
    64→        this.load.video(char.videoKey, char.videoPath);
    65→      }
    66→    }
    67→  }
