   275→  if (grade === 'R') {
   276→    if (duplicateCount >= 100) return 5;
   277→    if (duplicateCount >= 75)  return 4;
   278→    if (duplicateCount >= 50)  return 3;
   279→    if (duplicateCount >= 25)  return 2;
