   281→  } else if (grade === 'SR') {
   282→    if (duplicateCount >= 40) return 5;
   283→    if (duplicateCount >= 25) return 4;
   284→    if (duplicateCount >= 15) return 3;
   285→    if (duplicateCount >= 7)  return 2;
   286→    if (duplicateCount >= 3)  return 1;
