     1→import Phaser from 'phaser';
     2→import { BaseAbility } from './BaseAbility';
     3→import type { GameSceneAPI } from './types';
     4→import { SENTINEL_PARAMS } from '../config/abilityParams';
     5→
     6→/**
     7→ * 센티넬 (UR) — 보호막
     8→ * ★0: 2개 시작 / 300점마다 충전 / 최대 3  / ★1: 2개 / 250점마다 / 최대 4
     9→ * ★2: 3개 시작 / 200점마다 충전 / 최대 4  / ★3: 3개 / 150점마다 / 최대 5 + 흡수 시 연쇄 전기 3개 추가 제거
    10→ * - UI: 붉은 공이 허리 주변 수평 궤도 공전 + 전기 파지직 (재사용 Graphics)
    11→ */
    12→export class SentinelAbility extends BaseAbility {
    13→  private shieldCount = 0;
    14→  private orbitDroplets: Phaser.GameObjects.Graphics[] = [];
    15→  private orbitAngle = 0;
    16→
    17→  // ── 전기 스파크: persistent Graphics 재사용 (동적 생성 없음) ──
    18→  private sparkGfx: Phaser.GameObjects.Graphics | null = null;
    19→  private sparkTween: Phaser.Tweens.Tween | null = null;
    20→  private sparkTimer = 0;
    21→
    22→  private static readonly ORBIT_SPEED   = 3.0;
    23→  private static readonly ORBIT_RX      = 26;
    24→  private static readonly ORBIT_RY      = 7;
    25→  private static readonly ORBIT_WAIST_Y = 8;
    26→  private static readonly RED           = 0xff2222;
    27→  private static readonly RED_LIGHT     = 0xff6666;
    28→
    29→  override onCreate(api: GameSceneAPI): void {
    30→    this.shieldCount = SENTINEL_PARAMS.startShields;
    31→    this.spawnDroplets(api, SENTINEL_PARAMS.startShields);
    32→    this.sparkGfx = api.scene.add.graphics().setDepth(96).setAlpha(0);
    33→  }
    34→
    35→  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    36→    if (score % SENTINEL_PARAMS.chargeInterval === 0 && this.shieldCount < SENTINEL_PARAMS.maxShields) {
    37→      this.shieldCount++;
    38→      this.playShieldChargeEffect(api);
    39→      this.spawnDroplets(api, 1);
    40→    }
    41→  }
    42→
    43→  override onHitPoop(api: GameSceneAPI): boolean {
    44→    if (this.shieldCount > 0) {
    45→      this.shieldCount--;
    46→      this.scatterDroplets(api, 1);
    47→      this.playShieldBreakEffect(api);
    48→      this.zapNearbyPoops(api, 320);
    49→      return true;
    50→    }
    51→    return false;
    52→  }
    53→
    54→  override onUpdate(api: GameSceneAPI): void {
    55→    if (this.orbitDroplets.length === 0) return;
    56→
    57→    const delta  = api.scene.game.loop.delta / 1000;
    58→    const deltMs = api.scene.game.loop.delta;
    59→    this.orbitAngle += SentinelAbility.ORBIT_SPEED * delta;
    60→
    61→    const cx    = api.player.x;
    62→    const cy    = api.player.y + SentinelAbility.ORBIT_WAIST_Y;
    63→    const total = this.orbitDroplets.length;
    64→    const RX    = SentinelAbility.ORBIT_RX;
    65→    const RY    = SentinelAbility.ORBIT_RY;
    66→
    67→    this.orbitDroplets.forEach((drop, i) => {
    68→      if (!drop.active) return;
    69→      const angle = this.orbitAngle + (i / total) * Math.PI * 2;
    70→      const sinA  = Math.sin(angle);
    71→
    72→      drop.setPosition(cx + Math.cos(angle) * RX, cy + sinA * RY);
    73→
    74→      const t = (sinA + 1) / 2;
    75→      drop.setScale(0.55 + 0.55 * t);
    76→      drop.setAlpha(0.35 + 0.65 * t);
    77→      drop.setDepth(sinA > 0 ? 101 : 89);
    78→    });
    79→
    80→    // 전기 파지직: 250ms마다 persistent sparkGfx를 clear+redraw
    81→    this.sparkTimer += deltMs;
    82→    if (this.sparkTimer >= 250) {
    83→      this.sparkTimer = 0;
    84→      this.redrawSparks(api);
    85→    }
    86→  }
    87→
    88→  // ─────────────────────────────────────────────────────────────
    89→  // 리소스 정리 (게임 오버 시 GameScene에서 호출)
    90→  // ─────────────────────────────────────────────────────────────
    91→
    92→  override onDestroy(_api: GameSceneAPI): void {
    93→    this.sparkTween?.stop();
    94→    this.sparkGfx?.destroy();
    95→    this.orbitDroplets.forEach(drop => drop.destroy());
    96→    this.orbitDroplets = [];
    97→  }
    98→
    99→  // ─────────────────────────────────────────────────────────────
   100→  // 전기 스파크 (재사용 Graphics)
   101→  // ─────────────────────────────────────────────────────────────
   102→
   103→  /** persistent sparkGfx를 clear 후 몸+공 스파크를 새로 그리고 alpha tween */
   104→  private redrawSparks(api: GameSceneAPI): void {
   105→    const g = this.sparkGfx;
   106→    if (!g?.active) return;
   107→
   108→    g.clear();
   109→    g.setAlpha(1);
   110→    this.sparkTween?.stop();
   111→
   112→    // 몸 주변 스파크 (굵게)
   113→    const ba    = Phaser.Math.FloatBetween(0, Math.PI * 2);
   114→    const br    = Phaser.Math.FloatBetween(18, 34);
   115→    this.drawSparkLine(g, api.player.x + Math.cos(ba) * br, api.player.y + Math.sin(ba) * br * 0.6, 2.5, 10);
   116→
   117→    // 공 주변 스파크 (가늘게, 40% 확률 per droplet)
   118→    this.orbitDroplets.forEach(drop => {
   119→      if (drop.active && drop.alpha > 0.5 && Math.random() < 0.4) {
   120→        this.drawSparkLine(g, drop.x, drop.y, 1, 7);
   121→      }
   122→    });
   123→
   124→    this.sparkTween = api.scene.tweens.add({
   125→      targets: g,
   126→      alpha: 0,
   127→      duration: 200,
   128→      ease: 'Quad.easeOut',
   129→    });
   130→  }
   131→
   132→  /** 전달받은 Graphics에 지그재그 라인을 직접 그림 (새 객체 생성 없음) */
   133→  private drawSparkLine(g: Phaser.GameObjects.Graphics, ox: number, oy: number, thickness: number, segLen: number): void {
   134→    const color = Math.random() < 0.6 ? 0xff3333 : 0xff7744;
   135→    g.lineStyle(thickness, color, 1);
   136→    g.beginPath();
   137→    let px = ox + Phaser.Math.Between(-5, 5);
   138→    let py = oy + Phaser.Math.Between(-5, 5);
   139→    g.moveTo(px, py);
   140→    const segs = Phaser.Math.Between(2, 4);
   141→    for (let j = 0; j < segs; j++) {
   142→      px += Phaser.Math.Between(-segLen, segLen);
   143→      py += Phaser.Math.Between(-segLen, segLen);
   144→      g.lineTo(px, py);
   145→    }
   146→    g.strokePath();
   147→  }
   148→
   149→  // ─────────────────────────────────────────────────────────────
   150→  // 방울 관리
   151→  // ─────────────────────────────────────────────────────────────
   152→
   153→  private spawnDroplets(api: GameSceneAPI, count: number): void {
   154→    const scene = api.scene;
   155→    for (let i = 0; i < count; i++) {
   156→      const g = scene.add.graphics().setDepth(95);
   157→      this.drawDroplet(g);
   158→      g.setPosition(api.player.x, api.player.y + SentinelAbility.ORBIT_WAIST_Y);
   159→      g.setAlpha(0);
   160→      this.orbitDroplets.push(g);
   161→      scene.tweens.add({ targets: g, alpha: 1, scaleX: 1, scaleY: 1, duration: 350, delay: i * 50, ease: 'Back.easeOut' });
   162→    }
   163→  }
   164→
   165→  private scatterDroplets(api: GameSceneAPI, count: number): void {
   166→    const scene   = api.scene;
   167→    const removed = this.orbitDroplets.splice(0, count);
   168→    removed.forEach(drop => {
   169→      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
   170→      const dist  = Phaser.Math.FloatBetween(30, 55);
   171→      scene.tweens.add({
   172→        targets: drop,
   173→        x: drop.x + Math.cos(angle) * dist,
   174→        y: drop.y + Math.sin(angle) * dist,
   175→        alpha: 0, scaleX: 0.1, scaleY: 0.1,
   176→        duration: 120, ease: 'Quad.easeIn',
   177→        onComplete: () => drop.destroy(),
   178→      });
   179→    });
   180→  }
   181→
   182→  private drawDroplet(g: Phaser.GameObjects.Graphics): void {
   183→    g.clear();
   184→    g.fillStyle(SentinelAbility.RED, 0.22);
   185→    g.fillCircle(0, 0, 15);
   186→    g.fillStyle(SentinelAbility.RED, 0.4);
   187→    g.fillCircle(0, 0, 10);
   188→    g.fillStyle(SentinelAbility.RED, 0.95);
   189→    g.fillCircle(0, 0, 7);
   190→    g.fillStyle(0xffffff, 0.5);
   191→    g.fillCircle(-2, -2.5, 2.5);
   192→  }
   193→
   194→  // ─────────────────────────────────────────────────────────────
   195→  // 파장 범위 내 똥 제거
   196→  // ─────────────────────────────────────────────────────────────
   197→
   198→  private zapNearbyPoops(api: GameSceneAPI, radius: number): void {
   199→    const cx = api.player.x;
   200→    const cy = api.player.y;
   201→    const r2 = radius * radius;
   202→
   203→    const targets = (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
   204→      .filter(p => p.active && (p.x - cx) ** 2 + (p.y - cy) ** 2 <= r2);
   205→
   206→    if (targets.length === 0) return;
   207→
   208→    // 위치 저장 후 일괄 제거
   209→    const positions = targets.map(p => ({ x: p.x, y: p.y }));
   210→    targets.forEach(p => p.destroy());
   211→
   212→    // 단일 Graphics에 모든 위치 그리기 → 3회 redraw로 지글 효과
   213→    const zapG = api.scene.add.graphics().setDepth(155);
   214→    let frame   = 0;
   215→
   216→    const drawZapFrame = () => {
   217→      zapG.clear();
   218→      positions.forEach(pos => {
   219→        zapG.fillStyle(SentinelAbility.RED, 0.55 - frame * 0.12);
   220→        zapG.fillCircle(pos.x, pos.y, 10);
   221→        const sparks = Phaser.Math.Between(2, 3);
   222→        for (let i = 0; i < sparks; i++) {
   223→          this.drawSparkLine(
   224→            zapG,
   225→            pos.x + Phaser.Math.Between(-8, 8),
   226→            pos.y + Phaser.Math.Between(-8, 8),
   227→            Phaser.Math.FloatBetween(1.5, 2.5),
   228→            10
   229→          );
   230→        }
   231→      });
   232→      frame++;
   233→    };
   234→
   235→    drawZapFrame();
   236→
   237→    // 60ms, 120ms 후 redraw, 200ms 후 fade+destroy
   238→    [60, 120].forEach(delay => {
   239→      api.scene.time.delayedCall(delay, () => {
